"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73560"],{11456(e){e.exports=JSON.parse('{"id":"F127","slug":"return-on-assets","name":"Return on Assets (ROA)","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Return on assets (ROA)","level":"Beginner","aliases":["ROA","asset profitability","unlevered ROA"],"formula":{"latex":"ROA=\\\\frac{NI}{\\\\overline{TA}},\\\\quad ROA_{unlevered}=\\\\frac{NI+\\\\text{Interest}(1-t)}{\\\\overline{TA}}","also":[],"text":"ROA = Net income / Average total assets; Unlevered ROA = (Net income + Interest x (1 - tax rate)) / Average total assets"},"symbols":[{"symbol":"NI","meaning":"Net income","unit":"money"},{"symbol":"Average TA","meaning":"Average of the opening and closing total assets","unit":"money"},{"symbol":"t","meaning":"Tax rate","unit":"percent"},{"symbol":"Interest","meaning":"Interest expense","unit":"money"}],"when_to_use":"Use it to see how well a company turns its assets into profit. Net income is after interest, so a heavily indebted firm looks worse. The unlevered version adds back after-tax interest to compare firms with different debt levels.","worked_example":{"problem":"A company earned 90 after paying interest of 40. The tax rate is 25%. Total assets were 1,100 at the start of the year and 1,300 at the end.","inputs":{"ni":90,"int":40,"t":25,"a0":1100,"a1":1300},"steps":[{"label":"Average assets","working":"(1100+1300) / 2","value":"1,200.00"},{"label":"ROA = net income / average assets","working":"90 / 1200","value":"7.50%"},{"label":"Unlevered ROA = (NI + interest x (1 - t)) / average assets","working":"(90+40 x (1-0.25)) / 1200","value":"10.00%"}],"answer":"Average assets are 1,200.00. ROA is 7.50%. Adding back after-tax interest, the unlevered ROA is 10.00%, which shows what the assets earn before financing costs."},"calculator":{"available":true,"inputs":[{"id":"ni","label":"Net income","unit":"money","type":"number","default":90,"hint":""},{"id":"int","label":"Interest expense","unit":"money","type":"number","default":40,"hint":""},{"id":"t","label":"Tax rate","unit":"%","type":"number","default":25,"hint":""},{"id":"a0","label":"Total assets at start","unit":"money","type":"number","default":1100,"hint":""},{"id":"a1","label":"Total assets at end","unit":"money","type":"number","default":1300,"hint":""}],"checks":[],"steps":[{"id":"avg","label":"Average assets","expr":"(a0+a1)/2","format":"money"},{"id":"roa","label":"ROA = net income / average assets","expr":"ni/avg","format":"pct2"},{"id":"uroa","label":"Unlevered ROA = (NI + interest x (1 - t)) / average assets","expr":"(ni+int*(1-t))/avg","format":"pct2"}],"results":["roa","uroa"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"avg":1200,"roa":0.075,"uroa":0.1}},"finder":{"finds":"Profit earned per unit of assets","needs":"Net income, interest, tax rate, opening and closing assets"},"related":[{"slug":"return-on-equity","name":"Return on Equity (ROE)"},{"slug":"dupont-analysis","name":"DuPont Analysis (3-Step and 5-Step)"},{"slug":"profit-margins","name":"Profit Margins"}],"related_ids":["F128","F129","F066"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>R</mi><mi>O</mi><mi>A</mi><mo>=</mo><mfrac><mrow><mi>N</mi><mi>I</mi></mrow><mover accent=\\"true\\"><mrow><mi>T</mi><mi>A</mi></mrow><mo stretchy=\\"true\\">\u203E</mo></mover></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>R</mi><mi>O</mi><msub><mi>A</mi><mrow><mi>u</mi><mi>n</mi><mi>l</mi><mi>e</mi><mi>v</mi><mi>e</mi><mi>r</mi><mi>e</mi><mi>d</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>N</mi><mi>I</mi><mo>+</mo><mtext>Interest</mtext><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>t</mi><mo stretchy=\\"false\\">)</mo></mrow><mover accent=\\"true\\"><mrow><mi>T</mi><mi>A</mi></mrow><mo stretchy=\\"true\\">\u203E</mo></mover></mfrac></mrow><annotation encoding=\\"application/x-tex\\">ROA=\\\\frac{NI}{\\\\overline{TA}},\\\\quad ROA_{unlevered}=\\\\frac{NI+\\\\text{Interest}(1-t)}{\\\\overline{TA}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"margin-return","name":"Return on a Margin Purchase"},"next":{"slug":"return-on-equity","name":"Return on Equity (ROE)"},"lesson":{"name":"Lesson 6 \xb7 Ratios and trends","to":"/courses/financial-data-to-insight/ratios-and-trends"},"total":522}')}}]);